function buildEuropamundoTransferBlocks(title2, transfer, notesTitle) {
  const detailsLines = splitLinesFromMultilineText(transfer?.detalhes);
  const notesLines = splitLinesFromMultilineText(transfer?.notas);
  const detailGroups = splitLinesIntoPrintableGroups(detailsLines, 820);
  const noteGroups = splitLinesIntoPrintableGroups(notesLines, 820);
  const totalBlocks = Math.max(detailGroups.length, noteGroups.length, textValue2(transfer?.telefone_transferista) ? 1 : 0);
  if (!totalBlocks) return [];
  return Array.from({ length: totalBlocks }, (_, index138) => ({
    title: index138 === 0 ? title2 : `${title2} (continua\xE7\xE3o)`,
    detailsLines: detailGroups[index138] || [],
    phone: index138 === 0 ? textValue2(transfer?.telefone_transferista) : "",
    notesLines: noteGroups[index138] || [],
    notesTitle: noteGroups[index138]?.length ? index138 === 0 ? notesTitle : `${notesTitle} (continua\xE7\xE3o)` : ""
  }));
}
